import { describe, expect, it } from "vitest";
import { verifyHubPassword } from "../convex/infra/hubPassword";

// Generated by calling hashPassword and verifyPassword from apps/hub/src/runtime/users.ts,
// with NODE_TEST_CONTEXT=1. These are the Hub's production N=32768, r=8, p=1, salt=16, keylen=64.
// Keep the vectors literal: this catches both a format change and a hashing mismatch without
// making the backend's edge-runtime tests load the Hub's node:sqlite singleton.
const VECTORS = [
  {
    password: "correct horse battery staple",
    hash: "scrypt$32768$8$1$MsAG+jjRIM7+nfeKf/sNTA==$tcmPGn5EBf6KoJw57q+gviwfSjcpeRllG3XK1pMY2i0DWLsx7za3X1y9iCzhv16RN7r3aTbuB8HJekvH/TkpbQ==",
  },
  {
    password: "pässwörd ✓ 密码",
    hash: "scrypt$32768$8$1$PNoVff6OROcfAolnU4aD2A==$WA5+i+o60E0wOGGeVLaonwmpygwkhAfngL2/DId7VKSsDxWCGg6vLqSu80NskxgWec6v722v8VeK+ITi6Tfl+A==",
  },
];

describe("Hub password verifier", () => {
  it.each(VECTORS)(
    "accepts the Hub's hash for $password and rejects a wrong password",
    async ({ password, hash }) => {
      expect(await verifyHubPassword(password, hash)).toBe(true);
      expect(await verifyHubPassword(`${password}!`, hash)).toBe(false);
    },
  );

  it("does not normalize Unicode, matching the Hub's UTF-8 hashing", async () => {
    const { password, hash } = VECTORS[1];
    expect(await verifyHubPassword(password.normalize("NFD"), hash)).toBe(false);
  });

  it("rejects malformed hashes and parameters other than the Hub's exact work factor", async () => {
    const hash = VECTORS[0].hash;
    for (const stored of [
      "",
      hash.replace("32768", "1024"),
      hash.replace("32768", "1073741824"),
      hash.replace("$8$", "$16$"),
      hash.replace("$1$", "$0$"),
      `${hash}$extra`,
      hash.slice(0, -4),
      hash.replace("MsAG+jjRIM7+nfeKf/sNTA==", "!"),
      hash.replace("MsAG+jjRIM7+nfeKf/sNTA==", ""),
    ]) {
      expect(await verifyHubPassword("irrelevant", stored)).toBe(false);
    }
  });
});
